const skillNames={reading:'Reading',grammar:'Grammar',spelling:'Spelling',writing:'Writing'};
const intros={reading:'Read age-appropriate passages, find evidence, identify main ideas and make inferences.',grammar:'Learn a grammar rule, then apply it in short questions with immediate feedback.',spelling:'Study a spelling pattern or word group, then identify correct spellings.',writing:'Plan, draft and improve writing with a clear purpose, structure and checklist.'};
function storageKey(){return `skillup-english-${grade}-${skill}`}function getProgress(){try{return JSON.parse(localStorage.getItem(storageKey()))||{done:[]}}catch(e){return{done:[]}}}function setDone(i){const p=getProgress();if(!p.done.includes(i))p.done.push(i);localStorage.setItem(storageKey(),JSON.stringify(p));updateProgress()}function updateProgress(){const p=getProgress(),total=currentLessons().length;$('completeCount').textContent=`${p.done.length}/${total}`;$('englishMark').textContent=`Year ${grade} · ${p.done.length}/${total} ${skillNames[skill]}`;}function currentLessons(){return DATA[skill][grade]||[]}function setURL(){history.replaceState(null,'',`english-practice.html?grade=${grade}&skill=${skill}`)}function escapeHTML(s){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function spellingVariants(word){const set=new Set([word]),vowels='aeiou';if(word.length>3){set.add(word.slice(0,1)+word.slice(2));set.add(word.slice(0,-1)+word.at(-1)+word.at(-1));let a=word.split(''),i=Math.min(2,a.length-2);[a[i],a[i+1]]=[a[i+1],a[i]];set.add(a.join(''))}for(let i=0;i<word.length&&set.size<4;i++){if(vowels.includes(word[i].toLowerCase())){for(const v of vowels){if(v!==word[i].toLowerCase()){set.add(word.slice(0,i)+v+word.slice(i+1));break}}}}while(set.size<4)set.add(word+'e'.repeat(set.size-1));return[...set].slice(0,4).sort(()=>Math.random()-.5)}
function spellingQuestions(l){return l.words.map(w=>({q:'Which spelling is correct?',a:w,c:spellingVariants(w),hint:`Say “${w}” slowly and look for the spelling pattern from this lesson.`}))}
function renderTabs(){$('gradeSelect').value=grade;document.querySelectorAll('#skillTabs button').forEach(b=>b.classList.toggle('active',b.dataset.skill===skill));$('yearSkillTag').textContent=`YEAR ${grade} · ${skillNames[skill].toUpperCase()}`;$('workspaceTitle').textContent=`Year ${grade} ${skillNames[skill]}`;$('workspaceIntro').textContent=intros[skill]}
function renderLessons(){const ls=currentLessons(),p=getProgress(),host=$('lessonGrid');host.innerHTML='';ls.forEach((x,i)=>{const b=document.createElement('button');b.className=(i===lesson?'active ':'')+(p.done.includes(i)?'done':'');b.textContent=`${i+1}. ${x.t||x.title}`;b.onclick=()=>{lesson=i;qIndex=0;selected=null;answered=false;renderAll()};host.appendChild(b)});if(grade==='1'&&skill==='reading'){const a=document.createElement('a');a.href='english-year1-reading.html';a.className='library-link';a.textContent='📚 Open 30-passage Year 1 library →';host.appendChild(a)}}
function showOnly(id){['readingActivity','quizActivity','writingActivity'].forEach(x=>$(x).hidden=x!==id)}
function renderReading(){showOnly('readingActivity');const l=currentLessons()[lesson];$('learnTitle').textContent='Reading strategy';$('learnText').textContent=l.learn;$('passageLevel').textContent=`YEAR ${grade} READING`;$('passageTitle').textContent=l.t;$('passageText').textContent=l.p;qIndex=Math.max(0,Math.min(qIndex,l.qs.length-1));const q=l.qs[qIndex];$('questionCount').textContent=`Question ${qIndex+1} of ${l.qs.length}`;$('questionType').textContent=qIndex===l.qs.length-1?'THINK ABOUT THE WHOLE TEXT':'FIND EVIDENCE';$('readingQuestion').textContent=q[0];$('readingFeedback').textContent='';selected=null;answered=false;const host=$('readingAnswers');host.innerHTML='';q[1].forEach((v,i)=>{const b=document.createElement('button');b.textContent=v;b.onclick=()=>{if(answered)return;selected=i;answered=true;if(i===q[2]){b.classList.add('correct');$('readingFeedback').textContent='✓ Correct — well read.'}else{b.classList.add('wrong');host.children[q[2]].classList.add('correct');$('readingFeedback').textContent=`Not quite. ${q[3]}`}if(qIndex===l.qs.length-1)setDone(lesson)};host.appendChild(b)});$('readingPrev').disabled=qIndex===0;$('readingNext').textContent=qIndex===l.qs.length-1?'Finish lesson ✓':'Next →'}
function renderQuiz(){showOnly('quizActivity');const l=currentLessons()[lesson],isSpell=skill==='spelling',qs=isSpell?spellingQuestions(l):l.qs;$('learnTitle').textContent=l.t;$('learnText').textContent=l.learn;qIndex=Math.max(0,Math.min(qIndex,qs.length-1));const q=qs[qIndex];$('quizCount').textContent=`Question ${qIndex+1} of ${qs.length}`;$('quizType').textContent=isSpell?'SPELLING CHECK':'APPLY THE RULE';$('quizQuestion').textContent=isSpell?q.q:q[0];$('quizFeedback').textContent='';$('quizHint').textContent=isSpell?q.hint:q[3];selected=null;answered=false;const choices=isSpell?q.c:q[1],answer=isSpell?choices.indexOf(q.a):q[2],host=$('quizAnswers');host.innerHTML='';choices.forEach((v,i)=>{const b=document.createElement('button');b.textContent=v;b.onclick=()=>{if(answered)return;answered=true;selected=i;if(i===answer){b.classList.add('correct');$('quizFeedback').textContent='✓ Correct!'}else{b.classList.add('wrong');host.children[answer].classList.add('correct');$('quizFeedback').textContent='Review the rule above and compare the correct answer.'}if(qIndex===qs.length-1)setDone(lesson)};host.appendChild(b)});$('quizPrev').disabled=qIndex===0;$('quizNext').textContent=qIndex===qs.length-1?'Finish lesson ✓':'Next →'}
function renderWriting(){showOnly('writingActivity');const l=currentLessons()[lesson];$('learnTitle').textContent='Writing focus';$('learnText').textContent=`Plan before you draft. ${l.check[0]}. Then reread and improve your work.`;$('writingType').textContent=`YEAR ${grade} · ${l.t.toUpperCase()}`;$('writingTitle').textContent=l.title;$('writingPrompt').textContent=l.prompt;$('writingPlan').innerHTML=l.plan.map((x,i)=>`<div><b>${i+1}. Plan</b><span>${escapeHTML(x)}</span></div>`).join('');$('writingChecklist').innerHTML=l.check.map((x,i)=>`<label><input type="checkbox" data-check="${i}"> ${escapeHTML(x)}</label>`).join('');$('wordGoal').textContent=l.goal;const key=`skillup-writing-${grade}-${lesson}`;$('writingBox').value=localStorage.getItem(key)||'';countWords();$('writingFeedback').textContent=''}
function countWords(){const n=$('writingBox').value.trim()?$('writingBox').value.trim().split(/\s+/).length:0;$('wordCount').textContent=n}function renderActivity(){if(skill==='reading')renderReading();else if(skill==='writing')renderWriting();else renderQuiz()}function renderAll(){renderTabs();renderLessons();renderActivity();updateProgress();setURL()}
$('gradeSelect').onchange=e=>{grade=e.target.value;lesson=0;qIndex=0;renderAll()};document.querySelectorAll('#skillTabs button').forEach(b=>b.onclick=()=>{skill=b.dataset.skill;lesson=0;qIndex=0;renderAll()});$('readingPrev').onclick=()=>{if(qIndex){qIndex--;renderReading()}};$('readingNext').onclick=()=>{const l=currentLessons()[lesson];if(qIndex<l.qs.length-1){qIndex++;renderReading()}else{setDone(lesson);if(lesson<currentLessons().length-1){lesson++;qIndex=0;renderAll()}}};$('quizPrev').onclick=()=>{if(qIndex){qIndex--;renderQuiz()}};$('quizNext').onclick=()=>{const l=currentLessons()[lesson],qs=skill==='spelling'?spellingQuestions(l):l.qs;if(qIndex<qs.length-1){qIndex++;renderQuiz()}else{setDone(lesson);if(lesson<currentLessons().length-1){lesson++;qIndex=0;renderAll()}}};$('writingBox').addEventListener('input',countWords);$('clearWriting').onclick=()=>{$('writingBox').value='';countWords();$('writingFeedback').textContent='Draft cleared.'};$('saveWriting').onclick=()=>{localStorage.setItem(`skillup-writing-${grade}-${lesson}`,$('writingBox').value);setDone(lesson);$('writingFeedback').textContent='✓ Saved on this device. Use the checklist to edit and improve it.'};$('courseMenu').onclick=()=>$('courseNav').classList.toggle('open');if(!DATA[skill]||!DATA[skill][grade]){grade='1';skill='reading'}renderAll();